import { captureAuthUpdate } from './authUpdate';
import { gzipSync } from 'zlib';
import { z } from 'zod';
import { createLogger } from '../utils/logger';
import { getConfigManager } from './ConfigManager';
import { PROTOTYPE_HOST_URL, PROXY_URL } from '../config/proxy';
import { PrototypeBuildService } from './PrototypeBuildService';

const log = createLogger('PrototypeDeployService');
const HTML_ENTRY_PATH = 'index.html';
export const PROTOTYPE_SHARE_TITLE_MAX_LENGTH = 200;

export interface DeployResult {
  deployId: string;
  shareUrl: string;
}

const DeployResultSchema: z.ZodType<DeployResult> = z.object({
  deployId: z.string().min(1),
  shareUrl: z.string().url(),
});

export interface PrototypeDeployOptions {
  title?: string;
}

export interface StaticPrototypeDeployOptions extends PrototypeDeployOptions {
  entryPath: string;
}

export const normalizePrototypeShareTitle = (
  title?: string,
): string | undefined => {
  const trimmedTitle = title?.trim();
  if (!trimmedTitle) {
    return undefined;
  }
  return trimmedTitle.slice(0, PROTOTYPE_SHARE_TITLE_MAX_LENGTH);
};

export class PrototypeDeployService {
  private configManager = getConfigManager();

  constructor(
    private buildService: PrototypeBuildService = new PrototypeBuildService(),
    private hostUrl: string = PROTOTYPE_HOST_URL,
    private proxyUrl: string = PROXY_URL,
  ) {}

  async deploy(
    filesDir: string,
    options: PrototypeDeployOptions = {},
  ): Promise<DeployResult> {
    const { files, totalBytes } = await this.buildService.build(filesDir);
    return this.publishFiles(files, totalBytes, 'Built', options);
  }

  async deployStatic(
    filesDir: string,
    options: StaticPrototypeDeployOptions,
  ): Promise<DeployResult> {
    const { files, totalBytes } = await this.buildService.packStatic(
      filesDir,
      options.entryPath,
    );
    return this.publishFiles(files, totalBytes, 'Packed', options);
  }

  async deployHtml(
    html: string,
    options: PrototypeDeployOptions = {},
  ): Promise<DeployResult> {
    const content = Buffer.from(html, 'utf8').toString('base64');
    return this.publishFiles(
      [{ path: HTML_ENTRY_PATH, content }],
      Buffer.byteLength(html, 'utf8'),
      'Packed',
      options,
    );
  }

  private async publishFiles(
    files: { path: string; content: string }[],
    totalBytes: number,
    verb: string,
    options: PrototypeDeployOptions,
  ): Promise<DeployResult> {
    log.info(
      `${verb} prototype bundle: ${files.length} files, ${Math.round(
        totalBytes / 1024,
      )}KB`,
    );
    const title = normalizePrototypeShareTitle(options.title);
    const payload = gzipSync(
      Buffer.from(JSON.stringify({ files, ...(title ? { title } : {}) })),
    );
    return this.publish(payload, 0);
  }

  private async publish(
    payload: Buffer,
    retryCount: number,
  ): Promise<DeployResult> {
    const authToken = this.configManager.getAuthToken();
    if (!authToken) {
      throw new Error(
        'Not authenticated. Please run `rivet login` to deploy a prototype.',
      );
    }

    const response = await fetch(`${this.hostUrl}/publish`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${authToken}`,
        'Content-Type': 'application/json',
        'Content-Encoding': 'gzip',
      },
      body: new Uint8Array(payload),
    });

    if (response.status === 401 && retryCount === 0) {
      log.warn('Token expired, attempting to refresh...');
      const refreshed = await this.refreshAccessToken();
      if (refreshed) {
        return this.publish(payload, retryCount + 1);
      }
      throw new Error(
        'Authentication expired. Please run `rivet logout` and `rivet login` to re-authenticate.',
      );
    }

    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      const message =
        (body as { message?: string }).message ??
        `Deploy failed (${response.status}).`;
      throw new Error(message);
    }

    const result = DeployResultSchema.safeParse(await response.json());
    if (!result.success) {
      throw new Error('Deploy host returned an unexpected response.');
    }
    return result.data;
  }

  private async refreshAccessToken(): Promise<boolean> {
    const updateAuth = captureAuthUpdate(this.configManager);
    const refreshToken = this.configManager.getRefreshToken();
    if (!refreshToken) {
      log.warn('No refresh token available');
      return false;
    }
    try {
      const response = await fetch(`${this.proxyUrl}/api/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken }),
      });
      if (!response.ok) return false;
      const result = await response.json();
      if (result.success && result.token) {
        updateAuth(result);
        return true;
      }
      return false;
    } catch (err) {
      log.warn('Error refreshing token:', err);
      return false;
    }
  }
}
